mapper.select:
select g.name as gymName, u.tel as gymTel, u.created_at as regDate, ifnull(count(distinct m.id),0) as gymClientCount, ifnull(sum(p.payment_price*0.9),0) as gymCal from gym g left join user u on(g.user_id=u.id) left join member m on(g.id=m.gym_id) left join trainer t on(g.id=t.gym_id) left join payment p on(p.user_num=g.user_id)
And g.name like concat('%', #{gymName}, '%')
group by g.name, u.tel, u.created_at order by g.name limit #{row}, #{pageRow}

select t.name as trainerName, u.tel as trainerTel, u.created_at as regDate, ifnull(count(distinct m.id),0) as trainerClientCount, ifnull(sum(p.payment_price*0.9),0) as trainerCal from trainer t left join user u on(t.user_id=u.id) left join member m on(t.id=m.trainer_id) left join payment p on(p.user_num=t.user_id)
And t.name like concat('%', #{trainerName}, '%')
group by t.name, u.tel, u.created_at order by t.name limit #{row}, #{pageRow}

select m.name as clientName, u.tel as clientTel, u.created_at as regDate, m.trainer_id as ptTrainer, ifnull(sum(p.payment_price),0) as payment from member m left join user u on(m.user_id=u.id) left join payment p on(p.user_num=m.user_id)
And m.name like concat('%', #{clientName}, '%')
group by m.name, u.tel, u.created_at, m.trainer_id order by m.name limit #{row}, #{pageRow}
